window.OUTLET_REGION_MAP={Merbabu:'Kabupaten Klaten',Rajawali:'Kabupaten Klaten','Pemuda, Magelang':'Kota Magelang',Muntilann:'Kabupaten Magelang',Temanggung:'Kabupaten Temanggung',UNS:'Kota Surakarta',UMS:'Kabupaten Sukoharjo','Pasar Kliwon':'Kota Surakarta',Makamhaji:'Kabupaten Sukoharjo',Nusukan:'Kota Surakarta',Laweyan:'Kota Surakarta',Karanganyar:'Kabupaten Karanganyar',Boyolali:'Kabupaten Boyolali',Sragen:'Kabupaten Sragen',Sukoharjo:'Kabupaten Sukoharjo','Gajah Raya':'Kota Semarang',UDINUS:'Kota Semarang',UNNES:'Kota Semarang',UNDIP:'Kota Semarang',Sampangan:'Kota Semarang',Unimus:'Kota Semarang',Ngaliyan:'Kota Semarang',Banyumanik:'Kota Semarang',Ambarawa:'Kabupaten Semarang',UKSW:'Kota Salatiga',Godean:'Kabupaten Sleman',UMY:'Kabupaten Bantul','Jakal UII':'Kabupaten Sleman','Nusa Indah':'Kabupaten Sleman',Tajem:'Kabupaten Sleman'};
window.renderDemographics=(name,ring)=>{
 const record=window.DEMOGRAPHIC_DATA.records.find(r=>r.outletName===name&&r.ring===ring),el=document.querySelector('#demographics');
 if(!record){el.textContent='Profil demografi belum tersedia.';return;}
 const b=record.breakdown,n=new Intl.NumberFormat('id-ID'),round=v=>'≈'+n.format(Math.round(v/10)*10),pct=v=>(v/b.total*100).toLocaleString('id-ID',{maximumFractionDigits:1})+'%',num=v=>v.toLocaleString('id-ID',{maximumFractionDigits:2});
 const metric=(label,value,sub='')=>`<div class="demo-metric"><small>${label}</small><strong>${value}</strong><span>${sub}</span></div>`;
 const bands=[['Anak-anak',0,9],['Remaja awal',10,14],['Remaja akhir',15,19],['Dewasa muda',20,24],['Dewasa',25,34],['Dewasa',35,44],['Dewasa matang',45,59],['Lansia',60,99]];
 const groups=bands.map(([label,min,max])=>{const rows=b.ageGroups.filter(g=>Number(g.code)>=min&&Number(g.code)<=max);return {label,min,max,male:rows.reduce((s,g)=>s+g.male,0),female:rows.reduce((s,g)=>s+g.female,0),total:rows.reduce((s,g)=>s+g.total,0)};});
 const r=window.REGIONAL_DATA.records.find(r=>r.name===window.OUTLET_REGION_MAP[name]);
 el.innerHTML=`<div class="demo-head"><h3>Profil penduduk · ±${ring*400} m</h3><a class="text-link" href="${window.DEMOGRAPHIC_DATA.sourceUrl}" target="_blank" rel="noopener">WorldPop 2025 ↗</a></div><div class="demo-grid">${metric('Laki-laki',round(b.male),pct(b.male))}${metric('Perempuan',round(b.female),pct(b.female))}${metric('Kepadatan',n.format(Math.round(b.total/record.area)),'penduduk / km²')}</div><div class="demo-head"><h3>Kelompok umur & jenis kelamin</h3><label class="gender-control">Tampilkan<select id="market-gender"><option value="all">Semua penduduk</option><option value="female">Perempuan</option><option value="male">Laki-laki</option></select></label></div><div class="market-age-list" id="market-age-list"></div><details class="age-details"><summary>Rincian umur & jenis kelamin</summary><table><thead><tr><th>Umur</th><th>Laki-laki</th><th>Perempuan</th><th>Total</th></tr></thead><tbody>${b.ageGroups.map(g=>`<tr><td>${g.label}</td><td>${round(g.male)}</td><td>${round(g.female)}</td><td>${round(g.total)}</td></tr>`).join('')}</tbody></table></details>${r?`<div class="regional-context"><h3>Ekonomi & ketenagakerjaan</h3><span class="tag soft">${r.name} · BPS 2025 · seluruh kabupaten/kota</span><div class="demo-grid regional-grid">${metric('Penduduk miskin',num(r.poverty.rate)+'%','Maret 2025')}${metric('Garis kemiskinan','Rp'+n.format(r.poverty.povertyLineRupiahPerCapitaPerMonth),'per kapita / bulan')}${metric('Jumlah penduduk miskin',n.format(Math.round(r.poverty.poorPopulationThousands*1000)),'orang · Maret 2025')}${metric('Pengangguran (TPT)',num(r.labor.unemploymentRate)+'%','dari angkatan kerja · Agustus 2025')}${metric('Partisipasi kerja (TPAK)',num(r.labor.laborParticipationRate)+'%','penduduk 15+ · Agustus 2025')}</div><div class="source-inline"><a href="${r.poverty.sourceUrl}" target="_blank" rel="noopener">BPS ekonomi ↗</a><a href="${r.labor.sourceUrl}" target="_blank" rel="noopener">BPS tenaga kerja ↗</a></div></div>`:''}<details class="age-details"><summary>Data lainnya</summary><p class="fineprint">Pendapatan rumah tangga, jenis pekerjaan, pendidikan, dan status perkawinan pada radius ini belum tersedia.</p></details>`;
 const drawMarket=()=>{const gender=document.querySelector('#market-gender').value,denom=gender==='female'?b.female:gender==='male'?b.male:b.total;
 document.querySelector('#market-age-list').innerHTML=groups.map(g=>{const value=gender==='all'?g.total:g[gender],share=(value/denom*100).toLocaleString('id-ID',{maximumFractionDigits:1});return `<article class="market-age-row"><div class="market-age-title"><strong>${g.min}–${g.max===99?'60+':g.max}${g.max===99?'':' tahun'}</strong><span>${g.label}</span></div><div class="market-age-volume"><strong>${round(value)}</strong><small>${share}% dari ${gender==='female'?'perempuan':gender==='male'?'laki-laki':'penduduk'}</small><div class="age-track"><i style="width:${value/denom*100}%"></i></div></div><div class="market-sex"><span>Perempuan <b>${round(g.female)}</b></span><span>Laki-laki <b>${round(g.male)}</b></span></div></article>`;}).join('').replaceAll('60–60+','60+');
 };document.querySelector('#market-gender').onchange=drawMarket;drawMarket();
};
if(new URLSearchParams(location.search).get('embed')==='1'){document.documentElement.classList.add('embedded');new ResizeObserver(()=>parent.postMessage({type:'omaopa-radar-height',height:document.body.scrollHeight},location.origin)).observe(document.body);}
